315:     bool Socket::writeBytes(const std::string& str,
316:                             const CancellationRequest& isCancellationRequested)
317:     {
318:         int offset = 0;
319:         int len = (int) str.size();
320: 
321:         while (true)
322:         {
323:             if (isCancellationRequested && isCancellationRequested()) return false;
324: 
325:             ssize_t ret = send((char*) &str[offset], len);
326: 
327:             // We wrote some bytes, as needed, all good.
328:             if (ret > 0)
329:             {
330:                 if (ret == len)
331:                 {
332:                     return true;
333:                 }
334:                 else
335:                 {
336:                     offset += ret;
337:                     len -= ret;
338:                     continue;
339:                 }
340:             }
341:             // There is possibly something to be writen, try again
342:             else if (ret < 0 && Socket::isWaitNeeded())
343:             {
344:                 continue;
345:             }
346:             // There was an error during the write, abort
347:             else
348:             {
349:                 return false;
350:             }
351:         }
352:     }
