61:     {
62:         struct addrinfo hints;
63:         memset(&hints, 0, sizeof(hints));
64:         hints.ai_family = AF_UNSPEC;
65:         hints.ai_socktype = SOCK_STREAM;
66:         hints.ai_flags = AI_NUMERICSERV;
67: 
68:         // When the hostname is a numeric IP literal there is no name to resolve.
69:         // Setting AI_NUMERICHOST short-circuits getaddrinfo and, importantly, lets
70:         // us avoid AI_ADDRCONFIG: on glibc that flag enumerates the configured
71:         // interfaces through a netlink socket (__check_pf), a path that can abort
72:         // the whole process inside getaddrinfo (issue #560, reproduced with
73:         // "127.0.0.1") and that also fails to resolve loopback when the machine is
74:         // offline (issue #524).
75:         struct in6_addr dummy;
76:         bool numericHost = ix::inet_pton(AF_INET, hostname.c_str(), &dummy) == 1 ||
77:                            ix::inet_pton(AF_INET6, hostname.c_str(), &dummy) == 1;
78:         if (numericHost)
79:         {
80:             hints.ai_flags |= AI_NUMERICHOST;
