92:         // AI_ADDRCONFIG only returns addresses for families that have a configured,
93:         // non-loopback interface, so a host that resolves to loopback (e.g.
94:         // "localhost") fails to resolve when there is no network. Retry once
95:         // without the flag before giving up (issue #524).
96:         if (getaddrinfo_result != 0 && !numericHost)
97:         {
98:             hints.ai_flags &= ~AI_ADDRCONFIG;
