55:     std::pair<bool, std::vector<uint8_t>> load(const std::string& path)
56:     {
57:         std::vector<uint8_t> memblock;
58:         std::ifstream file(path);
59: 
60:         if (!file.is_open()) return std::make_pair(false, memblock);
61: 
62:         file.seekg(0, file.end);
63:         std::streamoff size = file.tellg();
64:         file.seekg(0, file.beg);
65: 
66:         memblock.reserve((size_t) size);
67:         memblock.insert(
68:             memblock.begin(), std::istream_iterator<char>(file), std::istream_iterator<char>());
69: 
70:         return std::make_pair(true, memblock);
71:     }
