217:     void AutobahnTestCase::run()
218:     {
219:         _webSocket.setUrl(_url);
220: 
221:         std::stringstream ss;
222:         log(std::string("Connecting to url: ") + _url);
223: 
224:         _webSocket.setOnMessageCallback([this](const ix::WebSocketMessagePtr& msg) {
225:             std::stringstream ss;
226:             if (msg->type == ix::WebSocketMessageType::Open)
227:             {
228:                 log("autobahn: connected");
229:                 ss << "Uri: " << msg->openInfo.uri << std::endl;
230:                 ss << "Handshake Headers:" << std::endl;
231:                 for (auto it : msg->openInfo.headers)
232:                 {
233:                     ss << it.first << ": " << it.second << std::endl;
234:                 }
235:             }
236:             else if (msg->type == ix::WebSocketMessageType::Close)
237:             {
238:                 ss << "autobahn: connection closed:";
239:                 ss << " code " << msg->closeInfo.code;
240:                 ss << " reason " << msg->closeInfo.reason << std::endl;
241: 
242:                 _condition.notify_one();
243:             }
244:             else if (msg->type == ix::WebSocketMessageType::Message)
245:             {
246:                 ss << "Received " << msg->wireSize << " bytes" << std::endl;
247: 
248:                 ss << "autobahn: received message: " << truncate(msg->str, 40) << std::endl;
249: 
250:                 _webSocket.send(msg->str, msg->binary);
251:             }
252:             else if (msg->type == ix::WebSocketMessageType::Error)
253:             {
254:                 ss << "Connection error: " << msg->errorInfo.reason << std::endl;
255:                 ss << "#retries: " << msg->errorInfo.retries << std::endl;
256:                 ss << "Wait time(ms): " << msg->errorInfo.wait_time << std::endl;
257:                 ss << "HTTP Status: " << msg->errorInfo.http_status << std::endl;
258: 
259:                 // And error can happen, in which case the test-case is marked done
260:                 _condition.notify_one();
261:             }
262:             else if (msg->type == ix::WebSocketMessageType::Fragment)
263:             {
264:                 ss << "Received message fragment" << std::endl;
265:             }
266:             else if (msg->type == ix::WebSocketMessageType::Ping)
267:             {
268:                 ss << "Received ping" << std::endl;
269:             }
270:             else if (msg->type == ix::WebSocketMessageType::Pong)
271:             {
272:                 ss << "Received pong" << std::endl;
273:             }
274:             else
275:             {
276:                 ss << "Invalid ix::WebSocketMessageType" << std::endl;
277:             }
278: 
279:             log(ss.str());
280:         });
281: 
282:         _webSocket.start();
283: 
284:         log("Waiting for test completion ...");
285:         std::unique_lock<std::mutex> lock(_mutex);
286:         _condition.wait(lock);
287: 
288:         _webSocket.stop();
289:     }
