291:     bool generateReport(const std::string& url)
292:     {
293:         ix::WebSocket webSocket;
294:         std::string reportUrl(url);
295:         reportUrl += "/updateReports?agent=ixwebsocket";
296:         webSocket.setUrl(reportUrl);
297:         webSocket.disableAutomaticReconnection();
298: 
299:         std::atomic<bool> success(true);
300:         std::condition_variable condition;
301: 
302:         webSocket.setOnMessageCallback([&condition, &success](const ix::WebSocketMessagePtr& msg) {
303:             if (msg->type == ix::WebSocketMessageType::Close)
304:             {
305:                 spdlog::info("Report generated");
306:                 condition.notify_one();
307:             }
308:             else if (msg->type == ix::WebSocketMessageType::Error)
309:             {
310:                 std::stringstream ss;
311:                 ss << "Connection error: " << msg->errorInfo.reason << std::endl;
312:                 ss << "#retries: " << msg->errorInfo.retries << std::endl;
313:                 ss << "Wait time(ms): " << msg->errorInfo.wait_time << std::endl;
314:                 ss << "HTTP Status: " << msg->errorInfo.http_status << std::endl;
315:                 spdlog::info(ss.str());
316: 
317:                 success = false;
318:             }
319:         });
320: 
321:         webSocket.start();
322:         std::mutex mutex;
323:         std::unique_lock<std::mutex> lock(mutex);
324:         condition.wait(lock);
325:         webSocket.stop();
326: 
327:         if (!success)
328:         {
329:             spdlog::error("Cannot generate report at url {}", reportUrl);
330:         }
331: 
332:         return success;
333:     }
