725:     void WebSocketConnect::start()
726:     {
727:         _webSocket.setUrl(_url);
728:         _webSocket.setExtraHeaders(_headers);
729: 
730:         if (_disablePerMessageDeflate)
731:         {
732:             _webSocket.disablePerMessageDeflate();
733:         }
734:         else
735:         {
736:             ix::WebSocketPerMessageDeflateOptions webSocketPerMessageDeflateOptions(
737:                 true, false, false, 15, 15);
738:             _webSocket.setPerMessageDeflateOptions(webSocketPerMessageDeflateOptions);
739:         }
740: 
741:         std::stringstream ss;
742:         log(std::string("Connecting to url: ") + _url);
743: 
744:         _webSocket.setOnMessageCallback([this](const ix::WebSocketMessagePtr& msg) {
745:             std::stringstream ss;
746:             if (msg->type == ix::WebSocketMessageType::Open)
747:             {
748:                 spdlog::info("ws_connect: connected");
749:                 spdlog::info("Uri: {}", msg->openInfo.uri);
750:                 spdlog::info("Headers:");
751:                 for (auto it : msg->openInfo.headers)
752:                 {
753:                     spdlog::info("{}: {}", it.first, it.second);
754:                 }
755:             }
756:             else if (msg->type == ix::WebSocketMessageType::Close)
757:             {
758:                 ss << "ws_connect: connection closed:";
759:                 ss << " code " << msg->closeInfo.code;
760:                 ss << " reason " << msg->closeInfo.reason << std::endl;
761:                 log(ss.str());
762:             }
763:             else if (msg->type == ix::WebSocketMessageType::Message)
764:             {
765:                 spdlog::info("Received {} bytes", msg->wireSize);
766: 
767:                 std::string payload = msg->str;
768:                 if (_decompressGzipMessages)
769:                 {
770:                     std::string decompressedBytes;
771:                     if (gzipDecompress(payload, decompressedBytes))
772:                     {
773:                         payload = decompressedBytes;
774:                     }
775:                     else
776:                     {
777:                         spdlog::error("Error decompressing: {}", payload);
778:                     }
779:                 }
780: 
781:                 ss << "ws_connect: received message: " << payload;
782:                 log(ss.str());
783:             }
784:             else if (msg->type == ix::WebSocketMessageType::Error)
785:             {
786:                 ss << "Connection error: " << msg->errorInfo.reason << std::endl;
787:                 ss << "#retries: " << msg->errorInfo.retries << std::endl;
788:                 ss << "Wait time(ms): " << msg->errorInfo.wait_time << std::endl;
789:                 ss << "HTTP Status: " << msg->errorInfo.http_status << std::endl;
790:                 log(ss.str());
791:             }
792:             else if (msg->type == ix::WebSocketMessageType::Fragment)
793:             {
794:                 spdlog::info("Received message fragment");
795:             }
796:             else if (msg->type == ix::WebSocketMessageType::Ping)
797:             {
798:                 spdlog::info("Received ping");
799:             }
800:             else if (msg->type == ix::WebSocketMessageType::Pong)
801:             {
802:                 spdlog::info("Received pong {}", msg->str);
803:             }
804:             else
805:             {
806:                 ss << "Invalid ix::WebSocketMessageType";
807:                 log(ss.str());
808:             }
809:         });
810: 
811:         _webSocket.start();
812:     }
