844:                                        tlsOptions,
845:                                        subprotocol,
846:                                        pingIntervalSecs,
847:                                        decompressGzipMessages);
848:         webSocketChat.start();
849: 
850:         while (true)
851:         {
852:             // Read line
853:             std::string line;
854:             auto quit = linenoise::Readline("> ", line);
855: 
856:             if (quit)
857:             {
858:                 break;
859:             }
860: 
