911:     int ws_gzip(const std::string& filename, int runCount)
912:     {
913:         auto res = readAsString(filename);
914:         bool found = res.first;
915:         if (!found)
916:         {
917:             spdlog::error("Cannot read content of {}", filename);
918:             return 1;
919:         }
920: 
921:         spdlog::info("gzip input: {} size {} cksum {}",
922:                      filename,
923:                      res.second.size(),
924:                      djb2HashStr(res.second));
925: 
926:         std::string compressedBytes;
927: 
928:         spdlog::info("compressing {} times", runCount);
929:         std::vector<uint64_t> durations;
930:         {
931:             Bench bench("compressing file");
932:             bench.setReported();
933: 
934:             for (int i = 0; i < runCount; ++i)
935:             {
936:                 bench.reset();
937:                 compressedBytes = gzipCompress(res.second);
938:                 bench.record();
939:                 durations.push_back(bench.getDuration());
940:             }
941: 
942:             size_t medianIdx = durations.size() / 2;
943:             uint64_t medianRuntime = durations[medianIdx];
944:             spdlog::info("median runtime to compress file: {}", medianRuntime);
945:         }
946: 
947:         std::string outputFilename(filename);
948:         outputFilename += ".gz";
949: 
950:         std::ofstream f;
951:         f.open(outputFilename);
952:         f << compressedBytes;
953:         f.close();
954: 
955:         spdlog::info("gzip output: {} size {} cksum {}",
956:                      outputFilename,
957:                      compressedBytes.size(),
958:                      djb2HashStr(compressedBytes));
959: 
960:         return 0;
961:     }
