1011:     int ws_autoroute(const std::string& url,
1012:                      bool disablePerMessageDeflate,
1013:                      const ix::SocketTLSOptions& tlsOptions,
1014:                      const std::string& subprotocol,
1015:                      int pingIntervalSecs,
1016:                      int msgCount)
1017:     {
1018:         Bench bench("ws_autoroute full test");
1019: 
1020:         // Our websocket object
1021:         ix::WebSocket webSocket;
1022: 
1023:         std::string fullUrl(url);
1024:         fullUrl += "/";
1025:         fullUrl += std::to_string(msgCount);
1026: 
1027:         webSocket.setUrl(fullUrl);
1028:         webSocket.setTLSOptions(tlsOptions);
1029:         webSocket.setPingInterval(pingIntervalSecs);
1030:         webSocket.disableAutomaticReconnection();
1031: 
1032:         if (disablePerMessageDeflate)
1033:         {
1034:             webSocket.disablePerMessageDeflate();
1035:         }
1036: 
1037:         if (!subprotocol.empty())
1038:         {
1039:             webSocket.addSubProtocol(subprotocol);
1040:         }
1041: 
1042:         std::atomic<uint64_t> receivedCountPerSecs(0);
1043:         std::atomic<uint64_t> target(msgCount);
1044:         std::mutex conditionVariableMutex;
1045:         std::condition_variable condition;
1046: 
1047:         std::atomic<bool> stop(false);
1048:         std::chrono::time_point<std::chrono::high_resolution_clock> start;
1049: 
1050:         // Setup a callback to be fired
1051:         // when a message or an event (open, close, ping, pong, error) is received
1052:         webSocket.setOnMessageCallback(
1053:             [&receivedCountPerSecs, &target, &stop, &condition, &bench, &start](
1054:                 const ix::WebSocketMessagePtr& msg) {
1055:                 if (msg->type == ix::WebSocketMessageType::Message)
1056:                 {
1057:                     receivedCountPerSecs++;
1058: 
1059:                     target -= 1;
1060:                     if (target == 0)
1061:                     {
1062:                         stop = true;
1063:                         condition.notify_one();
1064: 
1065:                         bench.report();
1066: 
1067:                         auto now = std::chrono::high_resolution_clock::now();
1068:                         auto milliseconds =
1069:                             std::chrono::duration_cast<std::chrono::milliseconds>(now - start);
1070:                         auto duration = milliseconds.count();
1071: 
1072:                         spdlog::info("AUTOROUTE IXWebSocket :: {} ms", duration);
1073:                     }
1074:                 }
1075:                 else if (msg->type == ix::WebSocketMessageType::Open)
1076:                 {
1077:                     bench.reset();
1078: 
1079:                     spdlog::info("ws_autoroute: connected");
1080:                     spdlog::info("Uri: {}", msg->openInfo.uri);
1081:                     spdlog::info("Headers:");
1082:                     for (auto it : msg->openInfo.headers)
1083:                     {
1084:                         spdlog::info("{}: {}", it.first, it.second);
1085:                     }
1086: 
1087:                     start = std::chrono::high_resolution_clock::now();
1088:                 }
1089:                 else if (msg->type == ix::WebSocketMessageType::Pong)
1090:                 {
1091:                     spdlog::info("Received pong {}", msg->str);
1092:                 }
1093:                 else if (msg->type == ix::WebSocketMessageType::Close)
1094:                 {
1095:                     spdlog::info("ws_autoroute: connection closed");
1096:                 }
1097:             });
1098: 
1099:         auto timer = [&receivedCountPerSecs, &stop] {
1100:             setThreadName("Timer");
1101:             while (!stop)
1102:             {
1103:                 //
1104:                 // We cannot write to sentCount and receivedCount
1105:                 // as those are used externally, so we need to introduce
1106:                 // our own counters
1107:                 //
1108:                 std::stringstream ss;
1109:                 ss << "messages received per second: " << receivedCountPerSecs;
1110: 
1111:                 spdlog::info(ss.str());
1112: 
1113:                 receivedCountPerSecs = 0;
1114: 
1115:                 auto duration = std::chrono::seconds(1);
1116:                 std::this_thread::sleep_for(duration);
1117:             }
1118:         };
1119: 
1120:         std::thread t1(timer);
1121: 
1122:         // Now that our callback is setup, we can start our background thread and receive messages
1123:         std::cout << "Connecting to " << url << "..." << std::endl;
1124:         webSocket.start();
1125: 
1126:         // Wait for all the messages to be received
1127:         std::unique_lock<std::mutex> lock(conditionVariableMutex);
1128:         condition.wait(lock);
1129: 
1130:         t1.join();
1131:         webSocket.stop();
1132: 
1133:         return 0;
1134:     }
