1136:     int ws_echo_server_main(int port,
1137:                             bool greetings,
1138:                             const std::string& hostname,
1139:                             const ix::SocketTLSOptions& tlsOptions,
1140:                             bool ipv6,
1141:                             bool disablePerMessageDeflate,
1142:                             bool disablePong,
1143:                             const std::string& httpHeaderAuthorization)
1144:     {
1145:         spdlog::info("Listening on {}:{}", hostname, port);
1146: 
1147:         ix::WebSocketServer server(port,
1148:                                    hostname,
1149:                                    SocketServer::kDefaultTcpBacklog,
1150:                                    SocketServer::kDefaultMaxConnections,
1151:                                    WebSocketServer::kDefaultHandShakeTimeoutSecs,
1152:                                    (ipv6) ? AF_INET6 : AF_INET);
1153: 
1154:         server.setTLSOptions(tlsOptions);
1155: 
1156:         if (disablePerMessageDeflate)
1157:         {
1158:             spdlog::info("Disable per message deflate");
1159:             server.disablePerMessageDeflate();
1160:         }
1161: 
1162:         if (disablePong)
1163:         {
1164:             spdlog::info("Disable responding to PING messages with PONG");
1165:             server.disablePong();
1166:         }
1167: 
1168:         server.setOnClientMessageCallback(
1169:             [greetings, httpHeaderAuthorization](std::shared_ptr<ConnectionState> connectionState,
1170:                                                  WebSocket& webSocket,
1171:                                                  const WebSocketMessagePtr& msg) {
1172:                 auto remoteIp = connectionState->getRemoteIp();
1173:                 if (msg->type == ix::WebSocketMessageType::Open)
1174:                 {
1175:                     spdlog::info("New connection");
1176:                     spdlog::info("remote ip: {}", remoteIp);
1177:                     spdlog::info("id: {}", connectionState->getId());
1178:                     spdlog::info("Uri: {}", msg->openInfo.uri);
1179:                     spdlog::info("Headers:");
1180:                     for (auto it : msg->openInfo.headers)
1181:                     {
1182:                         spdlog::info("{}: {}", it.first, it.second);
1183:                     }
1184: 
1185:                     if (!httpHeaderAuthorization.empty())
1186:                     {
1187:                         auto authorization = msg->openInfo.headers["Authorization"];
1188:                         if (authorization != httpHeaderAuthorization)
1189:                         {
1190:                             webSocket.close(4001, "Permission denied");
1191:                         }
1192:                         else
1193:                         {
1194:                             webSocket.sendText("Authorization suceeded!");
1195:                         }
1196:                     }
1197: 
1198:                     if (greetings)
1199:                     {
1200:                         webSocket.sendText("Welcome !");
1201:                     }
1202:                 }
1203:                 else if (msg->type == ix::WebSocketMessageType::Close)
1204:                 {
1205:                     spdlog::info("Closed connection: client id {} code {} reason {}",
1206:                                  connectionState->getId(),
1207:                                  msg->closeInfo.code,
1208:                                  msg->closeInfo.reason);
1209:                 }
1210:                 else if (msg->type == ix::WebSocketMessageType::Error)
1211:                 {
1212:                     spdlog::error("Connection error: {}", msg->errorInfo.reason);
1213:                     spdlog::error("#retries: {}", msg->errorInfo.retries);
1214:                     spdlog::error("Wait time(ms): {}", msg->errorInfo.wait_time);
1215:                     spdlog::error("HTTP Status: {}", msg->errorInfo.http_status);
1216:                 }
1217:                 else if (msg->type == ix::WebSocketMessageType::Message)
1218:                 {
1219:                     spdlog::info("Received {} bytes", msg->wireSize);
1220:                     webSocket.send(msg->str, msg->binary);
1221:                 }
1222:             });
1223: 
1224:         auto res = server.listen();
1225:         if (!res.first)
1226:         {
1227:             spdlog::error(res.second);
1228:             return 1;
1229:         }
1230: 
1231:         server.start();
1232:         server.wait();
1233: 
1234:         return 0;
1235:     }
